package com.spawnershop.service;
import com.spawnershop.api.*; import com.spawnershop.config.ShopItem; import com.spawnershop.data.StatisticsRepository; import com.spawnershop.economy.VaultEconomy; import com.spawnershop.util.Text; import org.bukkit.*; import org.bukkit.block.CreatureSpawner; import org.bukkit.entity.Player; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.BlockStateMeta; import org.bukkit.plugin.Plugin; import java.math.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public final class TransactionService { private final Plugin plugin; private final VaultEconomy eco; private final StatisticsRepository stats; private final Set<UUID> busy=ConcurrentHashMap.newKeySet(); public TransactionService(Plugin p,VaultEconomy e,StatisticsRepository s){plugin=p;eco=e;stats=s;}
 public void buy(Player p,ShopItem item,int amount){if(!worldAllowed(p)||!guard(p,item,"spawnershop.buy"))return; try{BigDecimal total=item.buy().multiply(BigDecimal.valueOf(amount)); if(!eco.has(p,total)){msg(p,"no-money");return;} ItemStack stack=stack(item,amount); if(!fits(p.getInventory(),stack)){msg(p,"no-space");return;} SpawnerBuyEvent event=new SpawnerBuyEvent(p,item,amount,total); Bukkit.getPluginManager().callEvent(event); if(event.isCancelled())return; if(!eco.withdraw(p,total)){msg(p,"no-money");return;} p.getInventory().addItem(stack); stats.log(p.getUniqueId(),item.id(),amount,total.doubleValue(),"BUY"); sound(p,"buy"); msg(p,"bought",amount,item.name(),eco.format(total));}finally{busy.remove(p.getUniqueId());}}
 public void sell(Player p,ShopItem item,int amount){if(!worldAllowed(p)||!guard(p,item,"spawnershop.sell"))return; try{int owned=count(p.getInventory(),item); int actual=Math.min(owned,amount); if(actual==0){p.sendMessage(Text.color("&cYou do not have that item."));return;} BigDecimal total=item.sell().multiply(BigDecimal.valueOf(actual)); SpawnerSellEvent event=new SpawnerSellEvent(p,item,actual,total); Bukkit.getPluginManager().callEvent(event); if(event.isCancelled())return; remove(p.getInventory(),item,actual); if(!eco.deposit(p,total)){p.getInventory().addItem(stack(item,actual)); p.sendMessage(Text.color("&cEconomy transaction failed."));return;} stats.log(p.getUniqueId(),item.id(),actual,total.doubleValue(),"SELL"); sound(p,"sell"); msg(p,"sold",actual,item.name(),eco.format(total));}finally{busy.remove(p.getUniqueId());}}
 /** Buys one of every enabled shop item in a single Vault withdrawal. */
 public void buyAll(Player p,Collection<ShopItem> source){if(!worldAllowed(p)||!p.hasPermission("spawnershop.buyall")||!busy.add(p.getUniqueId()))return;try{List<ShopItem> items=source.stream().filter(i->i.enabled()&&p.hasPermission("spawnershop.buy")&&(i.permission().isBlank()||p.hasPermission(i.permission()))).toList();if(items.isEmpty())return;BigDecimal total=items.stream().map(ShopItem::buy).reduce(BigDecimal.ZERO,BigDecimal::add);if(!eco.has(p,total)){msg(p,"no-money");return;}int empty=(int)Arrays.stream(p.getInventory().getStorageContents()).filter(Objects::isNull).count();if(empty<items.size()){msg(p,"no-space");return;}for(ShopItem item:items){SpawnerBuyEvent event=new SpawnerBuyEvent(p,item,1,item.buy());Bukkit.getPluginManager().callEvent(event);if(event.isCancelled())return;}if(!eco.withdraw(p,total)){msg(p,"no-money");return;}for(ShopItem item:items){Map<Integer,ItemStack> remaining=p.getInventory().addItem(stack(item,1));if(!remaining.isEmpty()){eco.deposit(p,total);p.getWorld().dropItemNaturally(p.getLocation(),remaining.values().iterator().next());return;}stats.log(p.getUniqueId(),item.id(),1,item.buy().doubleValue(),"BUY_ALL");}sound(p,"buy");p.sendMessage(Text.color("&aBought &e"+items.size()+" &aspawners for &e"+eco.format(total)+"&a."));}finally{busy.remove(p.getUniqueId());}}
 public int sellConfiguredItems(Player p,Map<Material,BigDecimal> prices){if(!worldAllowed(p)||!p.hasPermission("spawnershop.sellall")||!busy.add(p.getUniqueId()))return 0;try{BigDecimal total=BigDecimal.ZERO;int amount=0;ItemStack[] original=p.getInventory().getStorageContents();ItemStack[] storage=original.clone();for(int slot=0;slot<storage.length;slot++){ItemStack item=storage[slot];if(item==null)continue;BigDecimal price=prices.get(item.getType());if(price==null)continue;amount+=item.getAmount();total=total.add(price.multiply(BigDecimal.valueOf(item.getAmount())));storage[slot]=null;}if(amount==0){msg(p,"sell-all-none");return 0;}p.getInventory().setStorageContents(storage);if(!eco.deposit(p,total)){p.getInventory().setStorageContents(original);p.sendMessage(Text.color("&cEconomy transaction failed; items were not sold."));return 0;}sound(p,"sell");p.sendMessage(Text.color("&aSold &e"+amount+" &aitems for &e"+eco.format(total)+"&a."));return amount;}finally{busy.remove(p.getUniqueId());}}
 public int sellAll(Player p,Collection<ShopItem> items){ if(!worldAllowed(p)||!busy.add(p.getUniqueId()))return 0; int n=0; try{for(ShopItem i:items)if(i.enabled()&&i.sell().signum()>0){int a=count(p.getInventory(),i);ItemStack offhand=p.getInventory().getItemInOffHand();boolean sellOffhand=plugin.getConfig().getBoolean("settings.sell-all-include-offhand",true)&&same(offhand,i);if(sellOffhand)a+=offhand.getAmount();if(a>0){remove(p.getInventory(),i,a-(sellOffhand?offhand.getAmount():0));if(sellOffhand)p.getInventory().setItemInOffHand(null);BigDecimal total=i.sell().multiply(BigDecimal.valueOf(a));if(eco.deposit(p,total)){stats.log(p.getUniqueId(),i.id(),a,total.doubleValue(),"SELL");n+=a;}else{p.getInventory().addItem(stack(i,a-(sellOffhand?offhand.getAmount():0)));if(sellOffhand)p.getInventory().setItemInOffHand(offhand);}}}return n;}finally{busy.remove(p.getUniqueId());}}
 private boolean guard(Player p,ShopItem i,String perm){if(!i.enabled()){msg(p,"disabled");return false;} if(!p.hasPermission(perm)||(!i.permission().isBlank()&&!p.hasPermission(i.permission()))){msg(p,"no-permission");return false;}return busy.add(p.getUniqueId());}
 private boolean worldAllowed(Player p){if(plugin.getConfig().getStringList("settings.disabled-worlds").contains(p.getWorld().getName())){msg(p,"world-disabled");return false;}return true;}
 private void sound(Player p,String key){try{String sound=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(new java.io.File(plugin.getDataFolder(),"sounds.yml")).getString(key);if(sound!=null)p.playSound(p.getLocation(),Sound.valueOf(sound), (float)plugin.getConfig().getDouble("settings.sound-volume",1), (float)plugin.getConfig().getDouble("settings.sound-pitch",1));}catch(IllegalArgumentException ignored){}}
 public ItemStack stack(ShopItem i,int amount){ItemStack s=new ItemStack(i.material(),amount);var m=s.getItemMeta();m.displayName(net.kyori.adventure.text.Component.text(Text.color(i.name())));m.lore(Text.color(i.lore()).stream().map(x->net.kyori.adventure.text.Component.text(x.replace("${buy}",eco.format(i.buy())).replace("${sell}",eco.format(i.sell())))).toList());if(i.glow())m.addEnchant(org.bukkit.enchantments.Enchantment.UNBREAKING,1,true);if(i.material()==Material.SPAWNER&&i.mob()!=null&&m instanceof BlockStateMeta b&&b.getBlockState() instanceof CreatureSpawner sp){sp.setSpawnedType(i.mob());b.setBlockState(sp);}s.setItemMeta(m);return s;}
 private boolean same(ItemStack s,ShopItem i){if(s==null||s.getType()!=i.material())return false;if(i.material()!=Material.SPAWNER||i.mob()==null)return true;return s.getItemMeta() instanceof BlockStateMeta b&&b.getBlockState() instanceof CreatureSpawner sp&&sp.getSpawnedType()==i.mob();} private int count(Inventory inv,ShopItem i){return Arrays.stream(inv.getStorageContents()).filter(s->same(s,i)).mapToInt(ItemStack::getAmount).sum();} private void remove(Inventory inv,ShopItem i,int n){ItemStack[] storage=inv.getStorageContents();for(int slot=0;slot<storage.length&&n>0;slot++){ItemStack s=storage[slot];if(!same(s,i))continue;int take=Math.min(n,s.getAmount());s.setAmount(s.getAmount()-take);if(s.getAmount()==0)storage[slot]=null;n-=take;}inv.setStorageContents(storage);} private boolean fits(Inventory inv,ItemStack add){return inv.firstEmpty()!=-1||Arrays.stream(inv.getStorageContents()).anyMatch(s->s!=null&&s.isSimilar(add)&&s.getAmount()+add.getAmount()<=s.getMaxStackSize());} private void msg(Player p,String key,Object...v){String x=plugin.getConfig().getString("messages."+key);if(x==null){var f=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(new java.io.File(plugin.getDataFolder(),"messages.yml"));x=f.getString(key,key);}if(v.length>=3)x=x.replace("{amount}",String.valueOf(v[0])).replace("{item}",String.valueOf(v[1])).replace("{price}",String.valueOf(v[2]));p.sendMessage(Text.color(x));} }
